    // Загрузка полного CSS файла
    function loadFullCSS() {
        return new Promise(function(resolve) {
            try {
                var link = document.createElement('link');
                link.rel = 'stylesheet';
                link.href = 'steam.css?v=' + new Date().getTime();
                link.id = 'steam-full-css';
                
                link.onload = function() {
                    stylesLoaded = true;
                    hideLoadingIndicator();
                    resolve(true);
                };
                
                link.onerror = function() {
                    hideLoadingIndicator();
                    resolve(false);
                };
                
                document.head.appendChild(link);
                
            } catch (e) {
                console.error('Ошибка создания элемента link:', e);
                hideLoadingIndicator();
                resolve(false);
            }
        });
    }
    
    // Наблюдатель для динамических элементов
    function setupObserverForProblematicElements() {
        if (typeof MutationObserver === 'undefined') return;
        
        var observer = new MutationObserver(function(mutations) {
            for (var i = 0; i < mutations.length; i++) {
                if (mutations[i].addedNodes.length) {
                    applyStylesToDynamicElements();
                    break;
                }
            }
        });
        
        observer.observe(document.body, {
            childList: true,
            subtree: true
        });
        
        return observer;
    }
    
    // Применение стилей к динамическим элементам
    function applyStylesToDynamicElements() {
        try {
            var targetElements = document.querySelectorAll('.ip-YZhijAMZcuRoXBGiye ._1sCy-pm412Smb0wJx0W-4');
            
            for (var i = 0; i < targetElements.length; i++) {
                var element = targetElements[i];
                
                if (!element.getAttribute('data-custom-styled')) {
                    element.style.fontSize = '16px';
                    element.style.color = 'purple';
                    element.style.fontWeight = '100';
                    element.setAttribute('data-custom-styled', 'true');
                }
            }
        } catch (e) {
            console.error('Ошибка применения стилей к динамическим элементам:', e);
        }
    }
    
    // Основная функция инициализации
    function init() {
        // Создаем индикатор загрузки
        createLoadingIndicator();
        
        // Применяем критические стили
        applyCriticalStyles();
        
        // Загружаем полный CSS
        loadFullCSS().then(function(success) {
            if (success) {
                console.log('Steam CSS успешно загружен');
            } else {
                console.warn('Steam CSS не загружен, используются только критические стили');
            }
        });
        
        // Настраиваем наблюдатель для динамических элементов
        setupObserverForProblematicElements();
        
        // Применяем стили к уже существующим элементам
        setTimeout(applyStylesToDynamicElements, 1000);
        
        // Гарантированно скрываем индикатор через 5 секунд
        setTimeout(hideLoadingIndicator, 5000);
    }
    
    // Запускаем инициализацию после полной загрузки DOM
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        setTimeout(init, 500);
    }
    
